"""Inventory actual baseline reference styles. Never edits public templates."""
import collections,json,pathlib,re,sys
import tinycss2
root=pathlib.Path(__file__).resolve().parents[2];baseline=pathlib.Path(sys.argv[1]);manifest=json.loads((baseline/'snapshots.json').read_text());inventory={}
for route in ['/','/services','/about','/contact']:
 text=(baseline/manifest[route]['file']).read_text();rows=[]
 def rules(css,context='all'):
  for rule in tinycss2.parse_stylesheet(css,skip_comments=True,skip_whitespace=True):
   if rule.type=='at-rule' and rule.content:rules(tinycss2.serialize(rule.content),context+' / @'+rule.at_keyword+' '+tinycss2.serialize(rule.prelude).strip())
   if rule.type=='qualified-rule':
    selector=tinycss2.serialize(rule.prelude).strip()
    for d in tinycss2.parse_declaration_list(rule.content,skip_comments=True,skip_whitespace=True):
     if d.type=='declaration':rows.append({'context':context,'selector':selector,'property':d.name,'value':tinycss2.serialize(d.value).strip()})
 for css in re.findall(r'<style[^>]*>(.*?)</style>',text,re.S):rules(css)
 for i,style in enumerate(re.findall(r'\bstyle="([^"]*)"',text)):
  for d in tinycss2.parse_declaration_list(style,skip_comments=True,skip_whitespace=True):
   if d.type=='declaration':rows.append({'context':'inline','selector':f'inline[{i}]','property':d.name,'value':tinycss2.serialize(d.value).strip()})
 colours=collections.defaultdict(list)
 for row in rows:
  for color in re.findall(r'#[\da-fA-F]{3,8}\b|rgba?\([^)]*\)',row['value']):colours[color.lower()].append({k:row[k] for k in ['selector','property','context']})
 scene=sorted(set(re.findall(r'0x[\da-fA-F]{6}\b',text)))
 sections=[]
 for tag,attrs,body in re.findall(r'<(section|footer)\b([^>]*)>(.*?)</\1>',text,re.S):
  heading=re.search(r'<h[12][^>]*>(.*?)</h[12]>',body,re.S)
  sections.append({'tag':tag,'attributes':attrs.strip(),'heading':re.sub('<[^>]*>','',heading[1]) if heading else None})
 inventory[route]={'declarations':rows,'colours_and_actual_uses':dict(sorted(colours.items())),'scene_hex_literals':scene,'sections':sections,'script_urls':re.findall(r'<script[^>]+src="([^"]*)"',text),'css_urls':re.findall(r'<link[^>]+href="([^"]*)"[^>]*>',text)}
(root/'reports/phase-25-reference-tokens.json').write_text(json.dumps(inventory,indent=2)+'\n')
properties=['font-family','font-size','font-weight','line-height','letter-spacing','max-width','padding','padding-top','padding-bottom','margin','margin-bottom','gap','border-radius','box-shadow']
report=['# Phase 25 reference audit','', '## Scope and evidence', '', 'Report-only audit, taken from unmodified Phase 24b HEAD `164d6de41159385e151ecefec54763eab59141a5`. No page source was changed for this task. Stage 1 only. The exhaustive selector/declaration/inline-style/context and colour-use inventory is [phase-25-reference-tokens.json](phase-25-reference-tokens.json). It includes every actual reference declaration, not an invented replacement palette.', '', 'The source does **not** implement a uniform light reference system: default heroes and navigation are dark, Home/Services contain multiple dark bands, About has both dark and light bands, Contact is predominantly dark. There is no active light-theme toggle; dormant `data-theme="light"` selectors are not the default. References remain immutable. Pilots will borrow actual light-section surfaces and typography while following the requested light reading-area rule; this is a deliberate synthesis of existing roles, not a claim that the whole reference sequence already satisfies that rule.', '', '## Actual design tokens']
for route,data in inventory.items():
 report+=['',f'### `{route}`','', '| Property | Actual unique values |','| --- | --- |']
 for prop in properties:report.append('| '+prop+' | '+', '.join('`'+v.replace('|','\\|')+'`' for v in sorted({r['value'] for r in data['declarations'] if r['property']==prop}))+' |')
 report+=['','Breakpoints: '+', '.join('`'+v+'`' for v in sorted({r['context'] for r in data['declarations'] if r['context']!='all' and r['context']!='inline'})), '', 'Exact colour values and each selector/property use are in the inventory, including scene-only colours.']
report+=['', '## Reference skeleton and section sequence', '', '- Shared header: fixed 70px, 60px desktop insets, serif brand and Outfit navigation, responsive hamburger/menu; shared footer: void surface, grid of brand/navigation/destinations/guides/online locations/contact, legal/review row. Existing phone glyphs, footer contents and links are preserved.', '- Home: full-viewport centered dark animated hero; destinations (light); inline highlights (dark); Kodagu (light); why (light); counselling disclosures (dark); special circumstances (light); FAQ (light); team (dark); latest guides (dark); conversion (dark); tuition sources; dark footer. Reference contains pre-existing glass, hover transforms, badges, glow and noise. Do not reproduce those embellishments in the new pilots, and do not redesign the reference to remove them.', '- Services: 72vh dark mini hero; dark highlights and Germany; Italy light; UK dark; Czech light; Lithuania dark; Latvia light; Slovakia/Russia dark; GCC light; services/process/FAQ/source review; dark footer. Publication/status handling remains as-is.', '- About: 72vh dark mini hero; story, mission, values, Kodagu, light team, FAQ, source review and dark footer. Each section selector and exact declarations are captured in the inventory.', '- Contact: 88vh dark mini hero; contact form/details and FAQ; dark footer. Fields and delivery are not altered or submitted.', '', '## Template comparison', '', '| Template | Baseline differences from reference | Stage 1 decision |','| --- | --- | --- |','| Destination | 800px container including 60px gutters; centered article hero; all-dark long body; outlined pill; dark FAQ/author blocks | Germany only: reference-width outer grid, 70ch light reading lane, restrained dark hero; remove pill shape without changing its text |','| Place | Same article-shell drift and dark long body, 800px container; authored editorial/process/FAQ blocks | Mysuru only, same shared system |','| Blog index | 1200px outer grid; dark two-column cards, 18px radius, transforms/glow and tag pills | Light reference-style card grid, normal text categories, stable cards |','| Article | Centered 44/30px hero, dark long body, smaller 28px h2, gold links and dark tables | Choosing-consultant article only; short static hero, light prose/tables and reference serif hierarchy |','| Privacy / terms | Dark article-like legal text | Audit only; unchanged until owner approval |','| 404 | Existing utility treatment and discovery rules | Audit only; unchanged |','| All pages | Existing directory shell and grouped links | Audit only; unchanged |', '', '## Scene implementation and loading', '', 'Home, Services, About and Contact load Three.js r128, GSAP 3.12.2 and ScrollTrigger 3.12.2 using three deferred CDN scripts. Exact npm-mirror sizes: Three 603,113 bytes; GSAP 71,187 bytes; ScrollTrigger 42,334 bytes (CDP transfer accounting adds synthetic response overhead in the local lab). No scene image assets exist initially. Font CSS is render-blocking and requests Outfit and Cormorant Garamond with display=swap. Script URLs are exhaustive in the token inventory.', '', 'Home uses a fixed full-window WebGL canvas, 1600/500 far stars and 500/150 middle stars desktop/mobile, a wireframe globe/rings, orbiting caps, books and helix, with CSS vignette/nebula/grain and desktop floating SVGs. About/Services/Contact each have their own scene code. Existing reference render loops are requestAnimationFrame-driven; resize listeners update the renderer; mobile reduces object counts. Their source does not provide the new pilot Save-Data/hidden-tab guarantees. Do not silently rewrite these immutable reference scenes. The new global OFF switch may disable them explicitly; the default remains unchanged.', '', 'Pilot tiers must add no WebGL or JS library. Use a static scene still only if it can stay decorative, below 120KB per size and outside LCP, with a zero-resource palette fallback for JS-off/Save-Data. No parallax is needed. Articles use a shorter static hero. Other routes remain unopted-in.', '', '## Team inventory', '', 'Home: `#team .testi-grid` (three desktop columns, two at 769-1024px, one at <=768px), `.testi-card`, 40px desktop padding / 32px 26px mobile, original 16px radius and glass treatment. Photos are 96px circles. About: `.team-grid` three columns (two <=700px, one <=600px), 28px gap, 40px 32px padding, original 20px radius; photos 88px circles. About cards have centered names/titles and justified 14px bios; Home uses 15px bios. Preserve these layouts, photos, crops, names, titles and alt text. Grid auto rows currently make desktop cards equal within each row; one-column rows are content-sized, so equal-card-height treatment may be needed inside the authorized team area.', '', 'The full Jabir, Fawaz and Zaheer descriptions live in canonical Person data; About FAQ answers retain full bios, and both LLM files retain full descriptions. There is no separate long-form team biography section beyond those About FAQ answers; do not invent one or shorten those answers. The card paragraphs are the only replacement locations.', '', '| Exact supplied card | Characters including spaces and punctuation |','| --- | ---: |','| Jabir KJ | 127 |','| Zaheer KJ | 130 |','| Fawaz BH | 126 |','', 'Spread = 4, within the required maximum of 6. No wording changes needed.', '', 'Actual baseline card sizes at all requested widths: [phase-25-before-layout.json](phase-25-before-layout.json).', '', '## Baseline local measurements', '', 'Three cold Lighthouse mobile simulated Slow 4G / 4x CPU navigations per route. PHP 8.5 WASM adapter, Chromium 143, Lighthouse 12.8.2. External hosts are unavailable in this sandbox: exact JS versions and same font families/weights are mirrored from npm; production-absolute images are served from this checkout. This is a reproducible **local lab**, not production transfer compression, field CWV, native Apache/LiteSpeed, real CDN availability or contact-delivery evidence. Resource transfer figures are CDP-reported under those synthetic responses. All sample values, script payloads, render-blockers, LCP element and medians: [phase-25-before-metrics.json](phase-25-before-metrics.json). Blog index is included additionally so every pilot has a baseline.', '', '## Baseline screenshots', '', 'All four references and four future pilots were captured at 360, 768 and 1280px, height 900px, full-page. Motion is frozen and deterministic seeded scene geometry used solely by the capture harness, so frame timing cannot be mistaken for reference changes. Same-font npm mirrors are used; these are not actual Google Fonts network responses. Files: `reports/screenshots/phase-25/before-{home,services,about,contact,germany,mysuru,article,blog}-{360,768,1280}.png`. Screenshot completion and dimensions are recorded in the baseline layout JSON. No reference source was changed.']
(root/'reports/phase-25-audit.md').write_text('\n'.join(report)+'\n')
print('Audited',sum(len(v['declarations']) for v in inventory.values()),'declarations')
